// Device identity: an Ed25519 keypair that proves who this device is to a hub (see protocol hub.ts).
//
// - Browsers / Electron: a non-extractable keypair generated by WebCrypto and kept in IndexedDB
//   (CryptoKey objects are structured-cloneable, so the private key never exists as bytes in JS).
// - Mobile shell: the private key is exported once as PKCS8 and stored via the native secure store
//   (Keychain / Keystore); in memory it is re-imported as a non-extractable CryptoKey.
// - Tests / runtimes without storage: an in-memory store.
import { BizziError } from '@bizzi/protocol';
import type { Ed25519PublicJwk } from '@bizzi/protocol';
import { base64ToBytes, bytesToBase64, bytesToBase64Url } from './base64.ts';
import { getNative } from './native.ts';
import type { BizziNative } from './native.ts';

export interface DeviceIdentity {
  readonly keyId: string;
  readonly publicKey: Ed25519PublicJwk;
  /** base64url Ed25519 signature over the UTF-8 bytes of `message`. */
  sign(message: string): Promise<string>;
}

export interface StoredKeyPair {
  privateKey: CryptoKey;
  publicKey: Ed25519PublicJwk;
}

export interface IdentityStore {
  readonly kind: 'indexeddb' | 'native' | 'memory';
  load(keyId: string): Promise<StoredKeyPair | null>;
  create(keyId: string): Promise<StoredKeyPair>;
  delete(keyId: string): Promise<void>;
}

const ED25519 = { name: 'Ed25519' } as const;
const encoder = new TextEncoder();

function subtle(): SubtleCrypto {
  const s = globalThis.crypto?.subtle;
  if (!s) throw new BizziError('unsupported', 'WebCrypto is not available (a secure context is required)');
  return s;
}

async function generate(extractable: boolean): Promise<CryptoKeyPair> {
  try {
    return (await subtle().generateKey(ED25519, extractable, ['sign', 'verify'])) as CryptoKeyPair;
  } catch (e) {
    throw new BizziError('unsupported', `Ed25519 keys are not supported here: ${e instanceof Error ? e.message : String(e)}`);
  }
}

async function publicJwk(key: CryptoKey): Promise<Ed25519PublicJwk> {
  const jwk = await subtle().exportKey('jwk', key);
  if (jwk.kty !== 'OKP' || jwk.crv !== 'Ed25519' || typeof jwk.x !== 'string') throw new BizziError('internal', 'unexpected public key format');
  return { kty: 'OKP', crv: 'Ed25519', x: jwk.x };
}

function toIdentity(keyId: string, pair: StoredKeyPair): DeviceIdentity {
  return {
    keyId,
    publicKey: pair.publicKey,
    async sign(message: string): Promise<string> {
      const sig = await subtle().sign(ED25519, pair.privateKey, encoder.encode(message));
      return bytesToBase64Url(new Uint8Array(sig));
    },
  };
}

// ---------------------------------------------------------------- stores

export function memoryIdentityStore(): IdentityStore {
  const keys = new Map<string, StoredKeyPair>();
  return {
    kind: 'memory',
    async load(keyId) {
      return keys.get(keyId) ?? null;
    },
    async create(keyId) {
      const pair = await generate(false);
      const stored = { privateKey: pair.privateKey, publicKey: await publicJwk(pair.publicKey) };
      keys.set(keyId, stored);
      return stored;
    },
    async delete(keyId) {
      keys.delete(keyId);
    },
  };
}

interface NativeRecord {
  v: 1;
  pkcs8: string;
  publicKey: Ed25519PublicJwk;
}

/** Private key as PKCS8 in the platform secure store; a non-extractable copy lives in memory. */
export function nativeIdentityStore(native: BizziNative, prefix = 'bizzi.deviceKey.'): IdentityStore {
  const cache = new Map<string, StoredKeyPair>();
  const importPrivate = async (pkcs8: string): Promise<CryptoKey> => subtle().importKey('pkcs8', base64ToBytes(pkcs8) as Uint8Array<ArrayBuffer>, ED25519, false, ['sign']);
  return {
    kind: 'native',
    async load(keyId) {
      const hit = cache.get(keyId);
      if (hit) return hit;
      const raw = await native.secureGet(prefix + keyId);
      if (!raw) return null;
      let rec: NativeRecord;
      try {
        rec = JSON.parse(raw) as NativeRecord;
      } catch {
        return null;
      }
      if (rec.v !== 1 || !rec.pkcs8 || !rec.publicKey) return null;
      const stored = { privateKey: await importPrivate(rec.pkcs8), publicKey: rec.publicKey };
      cache.set(keyId, stored);
      return stored;
    },
    async create(keyId) {
      const pair = await generate(true);
      const pkcs8 = bytesToBase64(new Uint8Array(await subtle().exportKey('pkcs8', pair.privateKey)));
      const rec: NativeRecord = { v: 1, pkcs8, publicKey: await publicJwk(pair.publicKey) };
      await native.secureSet(prefix + keyId, JSON.stringify(rec));
      // Keep only a non-extractable copy in memory.
      const stored = { privateKey: await importPrivate(pkcs8), publicKey: rec.publicKey };
      cache.set(keyId, stored);
      return stored;
    },
    async delete(keyId) {
      cache.delete(keyId);
      await native.secureDelete(prefix + keyId);
    },
  };
}

interface IdbRecord {
  id: string;
  privateKey: CryptoKey;
  publicKey: Ed25519PublicJwk;
}

function idbRequest<T>(req: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error ?? new Error('IndexedDB request failed'));
  });
}

/** Non-extractable CryptoKeys persisted in IndexedDB. */
export function indexedDbIdentityStore(dbName = 'bizzi', storeName = 'deviceKeys'): IdentityStore {
  const cache = new Map<string, StoredKeyPair>();
  let dbp: Promise<IDBDatabase> | null = null;
  const db = (): Promise<IDBDatabase> => {
    if (!dbp) {
      dbp = new Promise((resolve, reject) => {
        const req = indexedDB.open(dbName, 1);
        req.onupgradeneeded = () => {
          if (!req.result.objectStoreNames.contains(storeName)) req.result.createObjectStore(storeName, { keyPath: 'id' });
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error ?? new Error('cannot open IndexedDB'));
      });
      dbp.catch(() => {
        dbp = null;
      });
    }
    return dbp;
  };
  const tx = async (mode: IDBTransactionMode): Promise<IDBObjectStore> => (await db()).transaction(storeName, mode).objectStore(storeName);
  return {
    kind: 'indexeddb',
    async load(keyId) {
      const hit = cache.get(keyId);
      if (hit) return hit;
      const rec = (await idbRequest((await tx('readonly')).get(keyId))) as IdbRecord | undefined;
      if (!rec?.privateKey || !rec.publicKey) return null;
      const stored = { privateKey: rec.privateKey, publicKey: rec.publicKey };
      cache.set(keyId, stored);
      return stored;
    },
    async create(keyId) {
      const pair = await generate(false);
      const rec: IdbRecord = { id: keyId, privateKey: pair.privateKey, publicKey: await publicJwk(pair.publicKey) };
      await idbRequest((await tx('readwrite')).put(rec));
      const stored = { privateKey: rec.privateKey, publicKey: rec.publicKey };
      cache.set(keyId, stored);
      return stored;
    },
    async delete(keyId) {
      cache.delete(keyId);
      await idbRequest((await tx('readwrite')).delete(keyId));
    },
  };
}

let defaultStore: IdentityStore | null = null;

/** Native secure store in the mobile shell, IndexedDB in browsers/Electron, else memory. */
export function defaultIdentityStore(): IdentityStore {
  if (defaultStore) return defaultStore;
  const native = getNative();
  if (native) defaultStore = nativeIdentityStore(native);
  else if (typeof indexedDB !== 'undefined') defaultStore = indexedDbIdentityStore();
  else defaultStore = memoryIdentityStore();
  return defaultStore;
}

/** Load the device key for `keyId` (e.g. a hub URL), creating it on first use. */
export async function loadOrCreateIdentity(keyId: string, store: IdentityStore = defaultIdentityStore()): Promise<DeviceIdentity> {
  const pair = (await store.load(keyId)) ?? (await store.create(keyId));
  return toIdentity(keyId, pair);
}

/** Load an existing device key, or null when this device was never set up for `keyId`. */
export async function loadIdentity(keyId: string, store: IdentityStore = defaultIdentityStore()): Promise<DeviceIdentity | null> {
  const pair = await store.load(keyId);
  return pair ? toIdentity(keyId, pair) : null;
}

/** Verify a signature made by `sign` (tests, and the UI mock hub). */
export async function verifySignature(publicKey: Ed25519PublicJwk, message: string, signature: Uint8Array<ArrayBuffer>): Promise<boolean> {
  const key = await subtle().importKey('jwk', publicKey, ED25519, true, ['verify']);
  return subtle().verify(ED25519, key, signature, encoder.encode(message));
}
